import{_t as e,it as t,n,rt as r}from"./chunks/framework.wyZghjns.js";var i=JSON.parse(`{"title":"Interface: IAuthProvider","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/auth/interfaces/IAuthProvider.md","filePath":"api/@jsprismarine/auth/interfaces/IAuthProvider.md"}`),a={name:`api/@jsprismarine/auth/interfaces/IAuthProvider.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/auth</a> / IAuthProvider</p><h1 id="interface-iauthprovider" tabindex="-1">Interface: IAuthProvider <a class="header-anchor" href="#interface-iauthprovider" aria-label="Permalink to “Interface: IAuthProvider”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/auth/src/IAuthProvider.ts#L48" target="_blank" rel="noreferrer">IAuthProvider.ts:48</a></p><p>Where a login identity comes from.</p><p>The seam exists so that what the bot harness needs - hundreds of throwaway identities, no network, no token cache - and what a real client needs are the same shape to everything upstream. It is also what keeps Xbox Live out of the headless build: a provider is chosen at the edge, and nothing in the client core imports one.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/auth/src/IAuthProvider.ts#L50" target="_blank" rel="noreferrer">IAuthProvider.ts:50</a></p><p>For logs and for choosing between cached sessions.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="createlogincredentials" tabindex="-1">createLoginCredentials() <a class="header-anchor" href="#createlogincredentials" aria-label="Permalink to “createLoginCredentials()”">​</a></h3><blockquote><p><strong>createLoginCredentials</strong>(<code>request</code>): <code>Promise</code>&lt;<a href="./LoginCredentials.html"><code>LoginCredentials</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/auth/src/IAuthProvider.ts#L67" target="_blank" rel="noreferrer">IAuthProvider.ts:67</a></p><p>Signs, or fetches, the credentials for one login.</p><p>Called once per connection attempt rather than cached, because the client data carries the address being dialled and the chain carries an expiry.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="request" tabindex="-1">request <a class="header-anchor" href="#request" aria-label="Permalink to “request”">​</a></h5><p><a href="./LoginRequest.html"><code>LoginRequest</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./LoginCredentials.html"><code>LoginCredentials</code></a>&gt;</p><hr><h3 id="getidentity" tabindex="-1">getIdentity() <a class="header-anchor" href="#getidentity" aria-label="Permalink to “getIdentity()”">​</a></h3><blockquote><p><strong>getIdentity</strong>(): <code>Promise</code>&lt;<a href="./Identity.html"><code>Identity</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/auth/src/IAuthProvider.ts#L59" target="_blank" rel="noreferrer">IAuthProvider.ts:59</a></p><p>The identity this provider will log in as.</p><p>Available before <a href="#createlogincredentials">createLoginCredentials</a> so a caller can label a connection before it has made one - a bot harness reporting which of five hundred it is waiting on, say.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Identity.html"><code>Identity</code></a>&gt;</p><hr><h3 id="getidentityprivatekey" tabindex="-1">getIdentityPrivateKey() <a class="header-anchor" href="#getidentityprivatekey" aria-label="Permalink to “getIdentityPrivateKey()”">​</a></h3><blockquote><p><strong>getIdentityPrivateKey</strong>(): <code>Promise</code>&lt;<code>string</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/auth/src/IAuthProvider.ts#L84" target="_blank" rel="noreferrer">IAuthProvider.ts:84</a></p><p>The private key, for the ECDH half of the encryption handshake.</p><p>Returned as a PEM-encoded PKCS#8 string rather than a <code>KeyObject</code> so that a provider backed by something that is not node&#39;s crypto stays possible.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code>&gt;</p><hr><h3 id="getidentitypublickey" tabindex="-1">getIdentityPublicKey() <a class="header-anchor" href="#getidentitypublickey" aria-label="Permalink to “getIdentityPublicKey()”">​</a></h3><blockquote><p><strong>getIdentityPublicKey</strong>(): <code>Promise</code>&lt;<code>string</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/3bcdb34ba3c7c38b61c3e86f7a9a78a6a6058b46/packages/auth/src/IAuthProvider.ts#L76" target="_blank" rel="noreferrer">IAuthProvider.ts:76</a></p><p>The public half of the key the chain is signed with, DER encoded and base64&#39;d - the same string the chain&#39;s <code>identityPublicKey</code> claim carries.</p><p>Encryption derives its shared secret from this key, so a provider has to expose it even though nothing in the login itself asks for it separately.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>string</code>&gt;</p>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};